x<-readLines("stdin",warn=FALSE);nm<-as.integer(strsplit(x[1],"\\s+")[[1]]);n<-nm[1];q<-nm[2];a<-do.call(rbind,strsplit(x[2:(n+1)],"\\s+"));queries<-x[(n+2):(n+1+q)];for(i in seq_along(queries)){s<-queries[i];p<-strsplit(s,"\\s+")[[1]];cat("Case ",i,": ",s,"\n",sep="");if(p[1]=="1"){r<-a[substr(a[,1],1,1)==p[2],,drop=FALSE];if(!nrow(r))cat("NA\n")else{r<-r[order(-as.integer(r[,2]),r[,1]),,drop=FALSE];for(j in seq_len(nrow(r)))cat(r[j,1]," ",r[j,2],"\n",sep="")}}else if(p[1]=="2"){r<-a[substr(a[,1],2,4)==p[2],,drop=FALSE];if(!nrow(r))cat("NA\n")else cat(nrow(r)," ",sum(as.integer(r[,2])),"\n",sep="")}else{r<-a[substr(a[,1],5,10)==p[2],,drop=FALSE];if(!nrow(r))cat("NA\n")else{rooms<-substr(r[,1],2,4);tt<-table(rooms);ord<-order(-as.integer(tt),names(tt));for(j in ord)cat(names(tt)[j]," ",tt[j],"\n",sep="")}}}
